import{_ as t,o as p,c as o,a3 as i}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"Blocking-Flow Research Centered on Idealized-System Flow Limiters","description":"","frontmatter":{"translationSource":{"title":"以理想系统限流器为核心的阻塞流研究","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=1kjqZ2UDFnqzhG8DpI00Pt","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/blocking-flow-research-centered-on-idealized-system-flow-limiters"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/blocking-flow-research-centered-on-idealized-system-flow-limiters"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/blocking-flow-research-centered-on-idealized-system-flow-limiters"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/blocking-flow-research-centered-on-idealized-system-flow-limiters"}]]},"headers":[],"relativePath":"blocking-flow-research-centered-on-idealized-system-flow-limiters.md","filePath":"logistics/src/page-1kjqZ2UDFnqzhG8DpI00Pt.md"}'),n={name:"blocking-flow-research-centered-on-idealized-system-flow-limiters.md"};function a(s,e,r,l,c,u){return p(),o("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><h1 id="blocking-flow-research-centered-on-idealized-system-flow-limiters" tabindex="-1">Blocking-Flow Research Centered on Idealized-System Flow Limiters <a class="header-anchor" href="#blocking-flow-research-centered-on-idealized-system-flow-limiters" aria-label="Permalink to &quot;Blocking-Flow Research Centered on Idealized-System Flow Limiters&quot;">​</a></h1><blockquote><p>Source page ID: <code>1kjqZ2UDFnqzhG8DpI00Pt</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=1kjqZ2UDFnqzhG8DpI00Pt" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Here is an example:</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a4c2e5db9af9088d.q90-a69a8e8abc6d87b9.webp" alt="Blocking-Flow Research Centered on Idealized-System Flow Limiters"></p><p>Related explanation</p><details><summary>Chat transcript</summary><p>xyIvneu_ 2026/5/9 12:47:38</p><p>This is pretty clear, right?</p><p>xyIvneu_ 2026/5/9 12:47:49</p><p>When belt 3 is empty, 4 and 5 are serviced round-robin.</p><p>xyIvneu_ 2026/5/9 12:47:59</p><p>Belt 3 has a duty cycle of 1/2.</p><p>xyIvneu_ 2026/5/9 12:50:20</p><p>I actually think this still has potential for development.</p><p>xyIvneu_ 2026/5/9 12:51:06</p><p>Because it is a different kind of device from fixed-rate control or fixed-ratio splitting.</p><p>xyIvneu_ 2026/5/9 12:51:14</p><p>It has something of a nonlinear character.</p><p>苍孤狼 2026/5/9 12:52:46</p><p>(<em>^▽^</em>)</p><p>@(<em>^▽^</em>) Position 3 has to be 1 tile.</p><p>苍孤狼 2026/5/9 12:53:19</p><p>Is that necessary for the blocking effect to work?</p><p>Cipolla_ 2026/5/9 12:53:33</p><p>We discussed this long ago.</p><p>(<em>^▽^</em>) 2026/5/9 12:53:38</p><p>Suppose 2 seconds is 1 unit of time.</p><p>Then per unit time,</p><p>1 carries 1 item.</p><p>Ports 2, 6, and 7 split equally at 1/3: each carries 2 units every 6 time units.</p><p>But in practice, once startup is complete, port 4 blocks completely, so port 7 carries one fewer, becoming 2 units every 5 time units.</p><p>Ports 2 and 6 then carry 2 units every 5 time units.</p><p>Port 3 is half of 2: 1 unit every 5 time units.</p><p>Thus, for the 3/4/5 merge on the right,</p><p>port 3 brings one unit of material every 5 time units, while 4 and 5 are blocked with continuous supply. The device&#39;s input-source sequence becomes the repeating cycle 34545.</p><p>Port 4&#39;s 2 units per 5 time units come from 7 and half of 2, balancing exactly.</p><p>Every 5 time units, port 5 brings in 2 material units and port 6 outputs 2, so the internal balance is stable.</p><p>Cipolla_ 2026/5/9 12:53:43</p><p>A good chance to hear what all the experts think.</p><p>苍孤狼 2026/5/9 12:54:20</p><p>I just want to derive a useful general theory and get awya from the Protocol Stash&#39;s restrictions.</p><p>苍孤狼 2026/5/9 12:54:28</p><p>Away.*</p><p>(<em>^▽^</em>) 2026/5/9 12:54:57</p><p>The key issue is that every Splitter/Converger pair needs at least one belt segment between them. Putting them directly together is far too likely to trigger a bug.</p><p>xyIvneu_ 2026/5/9 12:55:44</p><p>Protocol Stashes really are powerful.</p><p>xyIvneu_ 2026/5/9 12:56:16</p><p>Not using them is a bit of a self-imposed restriction.</p><p>(<em>^▽^</em>) 2026/5/9 12:56:40</p><p>The power of Protocol Stashes is equal splitting above a single belt&#39;s throughput. The same three-way mechanism might need two separate copies on belts.</p><p>苍孤狼 2026/5/9 12:56:44</p><p>The main thing is that Protocol Stashes take up space.</p><p>苍孤狼 2026/5/9 12:56:56</p><p>Everything else about them is perfect.</p><p>jnk 2026/5/9 12:57:41</p><p>Their footprint is already very small. Replacing one almost certainly costs more.</p><p>(<em>^▽^</em>) 2026/5/9 12:59:19</p><p>(<em>^▽^</em>) 2026/5/9 12:59:40</p><p>Let me optimize it: immediate startup, 2/5 speed.</p><p>caution</p><p>caution</p><p>2026/5/9 12:59:46</p><p>苍孤狼<br> @(<em>^▽^</em>) Position 3 has to be 1 tile.</p><p>@苍孤狼 It does not.</p><p>(<em>^▽^</em>) 2026/5/9 12:59:59</p><p>I am not sure whether a Belt Bridge will trigger a bug.</p><p>xyIvneu_ 2026/5/9 13:00:06</p><p>It will not.</p><p>(<em>^▽^</em>) 2026/5/9 13:00:06</p><p>If it does not, this is the coolest version.</p><p>xyIvneu_ 2026/5/9 13:00:14</p><p>Because this has already</p><p>xyIvneu_ 2026/5/9 13:00:16</p><p>been tested.</p><p>(<em>^▽^</em>) 2026/5/9 13:00:52</p><p>(<em>^▽^</em>) 2026/5/9 13:00:58</p><p>Then my optimization is done.</p><p>xyIvneu_ 2026/5/9 13:01:10</p><p>Barring surprises, this can be extended.</p><p>(<em>^▽^</em>) 2026/5/9 13:01:27</p><p>A stable rate of 2 items every 10 seconds.</p><p>xyIvneu_ 2026/5/9 13:01:37</p><p>And then get things like 4/9.</p><p>xyIvneu_ 2026/5/9 13:02:23</p><p>But right now we only need a component producing fifths,</p><p>xyIvneu_ 2026/5/9 13:02:31</p><p>so theoretically this is enough.</p><p>c 2026/5/9 13:03:26</p><p>(<em>^▽^</em>)</p><p>@(<em>^▽^</em>) This looks familiar.</p><p>苍孤狼 2026/5/9 13:03:59</p><p>@</p><p>caution</p><p>caution</p><p>☢caution☢caution☢<br> @苍孤狼 It does not.</p><p>@</p><p>caution</p><p>caution</p><p>Indeed.</p><p>(<em>^▽^</em>) 2026/5/9 13:04:01</p><p>I just shrank a group member&#39;s design to this footprint. A pretty good structure.</p><p>苍孤狼 2026/5/9 13:04:09</p><p>Really?</p><p>caution</p><p>caution</p><p>2026/5/9 13:04:28</p><p>It had actually already been shrunk (</p><p>xyIvneu_ 2026/5/9 13:05:03</p><p>Maybe everyone in the group has already succumbed to Protocol Stashes.</p><p>桜夜天華 2026/5/9 13:05:20</p><p>Not so.</p><p>caution</p><p>caution</p><p>2026/5/9 13:05:22</p><p>苍孤狼<br> Really?</p><p>@苍孤狼 Was there not already a proof last time?</p><p>桜夜天華 2026/5/9 13:05:25</p><p>I am a traditionalist.</p><p>(<em>^▽^</em>) 2026/5/9 13:05:28</p><p>Mine is now the same size as a Protocol Stash.</p><p>桜夜天華 2026/5/9 13:05:58</p><p>I would be delighted with a purely logistics-based construction.</p><p>(<em>^▽^</em>) 2026/5/9 13:06:03</p><p>Add another halving split and it is a 1/5-speed line.</p><p>madSUN 2026/5/9 13:06:23</p><p>xyIvneu_<br> Maybe everyone in the group has already succumbed to Protocol Stashes.</p><p>There is... no going back now...</p><p>(<em>^▽^</em>) 2026/5/9 13:06:44</p><p>Cipolla_</p><p>So which group member designed this? @Cipolla_</p><p>c 2026/5/9 13:06:53</p><p>That very person (</p><p>(<em>^▽^</em>) 2026/5/9 13:06:56</p><p>A stroke of genius in blocking.</p><p>Edward Kerman 2026/5/9 13:07:05</p><p>He has a whole bunch of other mysterious designs.</p><p>madSUN 2026/5/9 13:07:11</p><p>A god of blocking.</p><p>c 2026/5/9 13:07:20</p><p>I mean, we only learned about blocking after he joined.</p><p>Edward Kerman 2026/5/9 13:07:29</p><p>And it is uniform, too.</p><p>桜夜天華 2026/5/9 13:07:49</p><p>The father of flow limiters.</p><p>Edward Kerman 2026/5/9 13:07:53</p><p>But it has not yet been distilled into a formula.</p><p>Edward Kerman 2026/5/9 13:07:59</p><p>This is amazing.</p><p>苍孤狼 2026/5/9 13:08:01</p><p>So powerful.</p><p>madSUN 2026/5/9 13:08:11</p><p>Amazing! [tql]</p><p>(<em>^▽^</em>) 2026/5/9 13:08:17</p><p>jnk 2026/5/9 13:08:31</p><p>Edward Kerman<br> But it has not yet been distilled into a formula.</p><p>So when will someone distill it? (</p><p>Edward Kerman 2026/5/9 13:08:39</p><p>I cannot derive one.</p><p>(<em>^▽^</em>) 2026/5/9 13:08:59</p><p>My merged lines used to be a mess too.</p><p>Then I realized Convergers inherently exhaust the lower-volume source first.</p><p>Edward Kerman 2026/5/9 13:09:18</p><p>At present we can only try analyzing existing structures, not guide design.</p><p>(<em>^▽^</em>) 2026/5/9 13:09:28</p><p>For water to my 4 furnaces, I used to connect 3 branches to fresh supply and one to returned water.</p><p>(<em>^▽^</em>) 2026/5/9 13:09:42</p><p>But later found that directly merging them works.</p><p>(<em>^▽^</em>) 2026/5/9 13:09:57</p><p>Balancing? The Converger will handle it.</p><p>苍孤狼 2026/5/9 13:11:46</p><p>@</p><p>caution</p><p>caution</p><p>☢caution☢caution☢<br> @苍孤狼 It does not.</p><p>@</p><p>caution</p><p>caution</p><p>It really does not.</p><p>苍孤狼 2026/5/9 13:11:52</p><p>苍孤狼 2026/5/9 13:12:01</p><p>So this definitely is not a specially tuned structure.</p><p>苍孤狼 2026/5/9 13:12:12</p><p>It can be described in general terms.</p><p>c 2026/5/9 13:12:28</p><p>If two kinds of blocking have the same ratio, can we call them isomorphic?</p><p>苍孤狼 2026/5/9 13:12:31</p><p>We just do not know how yet.</p><p>(<em>^▽^</em>) 2026/5/9 13:12:37</p><p>Once you understand how it works, you can adjust it yourself.</p><p>苍孤狼 2026/5/9 13:13:24</p><p>I mean deriving a theory that directly gives 2/7, 2/11, 7/23, etc.</p><p>(<em>^▽^</em>) 2026/5/9 13:13:34</p><p>There is no need that abstract.</p><p>caution</p><p>caution</p><p>2026/5/9 13:13:47</p><p>The final result of this structure can be worked out on paper.</p><p>(<em>^▽^</em>) 2026/5/9 13:13:51</p><p>The largest prime appearing in material ratios is only 5.</p><p>苍孤狼 2026/5/9 13:13:52</p><p>Do people doing cursed engineering care about practical need?</p><p>苍孤狼 2026/5/9 13:14:16</p><p>Ever since uniform splitting, practical need has been optional.</p><p>(<em>^▽^</em>) 2026/5/9 13:14:25</p><p>You can directly make optimal 1/5-, 3/5-, and 4/5-speed limiters.</p><p>caution</p><p>caution</p><p>2026/5/9 13:14:31</p><p>Route length does not affect the result.</p><p>(<em>^▽^</em>) 2026/5/9 13:14:34</p><p>The 2/5-speed version is already optimal.</p><p>(<em>^▽^</em>) 2026/5/9 13:14:48</p><p>Go on, optimize it. I want to see the smallest one.</p><p>xyIvneu_ 2026/5/9 13:15:03</p><p>This really could be a new approach to rational-rate uniformity.</p><p>(<em>^▽^</em>) 2026/5/9 13:15:06</p><p>Speaking of which, is our obsession with little belts another kind of ‘copper refining’? [A Chinese pun on attraction to minors.]</p><p>xyIvneu_ 2026/5/9 13:15:16</p><p>It is essentially an iterative method.</p><p>(<em>^▽^</em>) 2026/5/9 13:15:22</p><p>And is posting blueprints in the group another kind of exhibitionism?</p><p>Fatal Error A1012 2026/5/9 13:15:22</p><p>xyIvneu_ 2026/5/9 13:15:32</p><p>Could iteration also produce irrational-rate uniformity?</p><p>苍孤狼 2026/5/9 13:15:36</p><p>Mathematics has long since advanced beyond research driven solely by the needs of physics.</p><p>xyIvneu_ 2026/5/9 13:15:41</p><p>That would be incredible.</p><p>caution</p><p>caution</p><p>2026/5/9 13:15:43</p><p>Why is this iterative?</p><p>Fatal Error A1012 2026/5/9 13:15:49</p><p>So you can stack blocking that multiplies by 1/2, right?</p><p>(<em>^▽^</em>) 2026/5/9 13:16:00</p><p>Fatal Error A1012</p><p>@Fatal Error A1012 I know that, but I suggest not connecting Convergers and Splitters directly; it is very easy to make something glitch.</p><p>xyIvneu_ 2026/5/9 13:16:04</p><p>It iterates using a uniform 1/2 flow.</p><p>jnk 2026/5/9 13:16:19</p><p>(<em>^▽^</em>)<br> And is posting blueprints in the group another kind of exhibitionism?</p><p>？</p><p>xyIvneu_ 2026/5/9 13:16:24</p><p>xyIvneu_<br> It iterates using a uniform 1/2 flow.</p><p>Iterate occupied slots into 1/3 and empty slots into 1/2.</p><p>Fatal Error A1012 2026/5/9 13:16:43</p><p>No, just do not connect a Splitter output to a Converger.</p><p>(<em>^▽^</em>) 2026/5/9 13:16:55</p><p>c 2026/5/9 13:17:46</p><p>A newcomer joins and immediately sees the group&#39;s exhibitionism.</p><p>caution</p><p>caution</p><p>2026/5/9 13:17:50</p><p>Is that how to understand it?</p><p>Fatal Error A1012 2026/5/9 13:18:22</p><p>There is no general solution for spatial compression, but without considering space there might be a general structure.</p><p>c 2026/5/9 13:18:46</p><p>Is there not one already?</p><p>(<em>^▽^</em>) 2026/5/9 13:18:48</p><p>Compression has to avoid Hypergryph&#39;s little ‘clever touches.’</p><p>c 2026/5/9 13:18:50</p><p>Binary blocking.</p><p>c 2026/5/9 13:18:54</p><p>(<em>^▽^</em>) 2026/5/9 13:19:13</p><p>Was the biggest killer of oscillating power generation not Splitter/Converger bugs causing a collapse?</p><p>Fatal Error A1012 2026/5/9 13:19:18</p><p>But we want rational rates.</p><p>jnk 2026/5/9 13:19:21</p><p>xyIvneu_<br> It iterates using a uniform 1/2 flow.</p><p>Would the iteration not be truncated by limited belt length? lol</p><p>(<em>^▽^</em>) 2026/5/9 13:19:38</p><p>Excessive length makes startup take too long.</p><p>xyIvneu_ 2026/5/9 13:19:39</p><p>jnk<br> Would the iteration not be truncated by limited belt length? lol</p><p>Thinking about it, that is possible.</p><p>xyIvneu_ 2026/5/9 13:19:55</p><p>Because, honestly, the leap-year method is also essentially iterative.</p><p>c 2026/5/9 13:20:06</p><p>I mean rational blocking using binary encoding of disposal/recirculation.</p><p>jnk 2026/5/9 13:20:10</p><p>(<em>^▽^</em>)<br> Was the biggest killer of oscillating power generation not Splitter/Converger bugs causing a collapse?</p><p>Was the biggest killer not non-uniformity making the stored-energy range too large? (</p><p>xyIvneu_ 2026/5/9 13:20:13</p><p>With proper optimization, those two have equivalent complexity.</p><p>(<em>^▽^</em>) 2026/5/9 13:20:59</p><p>jnk<br> Was the biggest killer not non-uniformity making the stored-energy range too large? (</p><p>@jnk That was pushing too close to the limit, plus unstable battery input frequency causing stored energy to hit 0 at one point.</p><p>Ekichuro 2026/5/9 13:21:24</p><p>When will Hypergryph release a rate limiter and settle this? )</p><p>(<em>^▽^</em>) 2026/5/9 13:21:41</p><p>When modifying an oscillating loop, Convergers and Splitters can easily end up outputting in only one direction.</p><p>(<em>^▽^</em>) 2026/5/9 13:21:59</p><p>My Valley setup suffered from it once. The calculations were all correct, yet the generators all ended up holding 50.</p><p>(<em>^▽^</em>) 2026/5/9 13:22:14</p><p>Placing it again fixed it.</p><p>(<em>^▽^</em>) 2026/5/9 13:22:33</p><p>Or split off half at the very beginning to reduce the chance of a lockup.</p><p>xyIvneu_ 2026/5/9 13:22:42</p><p>Putting Splitters and Convergers together does cause problems.</p><p>xyIvneu_ 2026/5/9 13:22:56</p><p>Who knows which ancient version that oscillating-power design came from.</p><p>(<em>^▽^</em>) 2026/5/9 13:23:14</p><p>Yes. That is why none of my mechanisms directly connect Splitters and Convergers now.</p><p>(<em>^▽^</em>) 2026/5/9 13:23:25</p><p>Hypergryph&#39;s little “clever touches” are still too powerful.</p><p>c 2026/5/9 13:24:07</p><p>Cipolla_<br> [Image]...</p><p>@Cipolla_ After searching for ages, I finally found it.</p><p>(<em>^▽^</em>) 2026/5/9 13:24:10</p><p>But there is no need for oscillating generation now, so it does not really matter.</p><p>c 2026/5/9 13:24:34</p><p>c<br> @(<em>^▽^</em>) This looks familiar...</p><p>So that is why it looked familiar.</p><p>Fatal Error A1012 2026/5/9 13:24:53</p><p>Great, I have a whole bunch of structures like this. As long as I leave them alone, they will be fine.</p><p>(<em>^▽^</em>) 2026/5/9 13:25:34</p><p>So had he already posted this optimized version too?</p><p>(<em>^▽^</em>) 2026/5/9 13:25:37</p><p>I cannot see the records.</p><p>caution</p><p>caution</p><p>2026/5/9 13:25:51</p><p>He posted it right at the beginning (</p><p>c 2026/5/9 13:26:00</p><p>(<em>^▽^</em>) 2026/5/9 13:26:15</p><p>I have only seen the later one since joining the group.</p><p>jnk 2026/5/9 13:26:15</p><p>c 2026/5/9 13:26:24</p><p>[Group chat transcript]</p><p>(<em>^▽^</em>) 2026/5/9 13:26:28</p><p>This seems a little too ancient.</p><p>c 2026/5/9 13:26:48</p><p>The father of flow limiters says so (</p><p>(<em>^▽^</em>) 2026/5/9 13:26:56</p><p>But the lower one is very helpful for understanding.</p><p>(<em>^▽^</em>) 2026/5/9 13:27:13</p><p>As for the upper one, forgive me, but I cannot explain it.</p><p>Fatal Error A1012 2026/5/9 13:28:38</p><p>This compression method actually looks a little like 22 mixed belts—only in shape.</p><p>Fatal Error A1012 2026/5/9 13:28:57</p><p>xyIvneu_ 2026/5/9 13:29:49</p><p>Fatal Error A1012</p><p>This is even more blatantly brute-force phase adjustment.</p><p>(<em>^▽^</em>) 2026/5/9 13:30:27</p><p>Speaking of which, is our pursuit of small production lines also a kind of “copper-refining obsession”? [A Chinese pun on attraction to minors.]</p><p>And is bringing blueprints into the group a kind of exhibitionism?</p><p>Is forwarding someone else&#39;s blueprint a kind of NTR?</p><p>Is exchanging blueprints a kind of wife-swapping play?</p><p>Is mangling someone else&#39;s blueprint until it stops working a kind of corruption?</p><p>jnk 2026/5/9 13:30:47</p><p>xyIvneu_  13:32:17</p><p>Surely this group would not modify someone else&#39;s blueprint until it stops working.</p><p>jnk  13:32:49</p><p>This group modifies other people&#39;s blueprints when they do not work ()</p><p>c  13:33:05</p><p>(<em>^▽^</em>)<br> As for the upper one, forgive me, but I cannot explain it.</p><p>@(<em>^▽^</em>) Is it not just the lower one folded over to the top?</p><p>(<em>^▽^</em>)  13:33:12</p><p>Mm.</p><p>(<em>^▽^</em>)  13:33:27</p><p>But if you gave me this one first, I would not be able to make sense of it.</p><p>Fatal Error A1012  13:33:44</p><p>Yes, that is how the compression came about.</p><p>(<em>^▽^</em>)  13:33:44</p><p>Even after making sense of it, I still could not explain it clearly.</p><p>c  13:34:00</p><p>So the two are essentially the same. What is that called in geometry again?</p><p>Fatal Error A1012  13:34:24</p><p>-&gt;</p><p>xyIvneu_  13:34:28</p><p>Topological isomorphism, perhaps.</p><p>jnk  13:35:15</p><p>Graph isomorphism ()</p><p>xyIvneu_  13:35:29</p><p>Graph would work too, right?</p><p>xyIvneu_  13:35:37</p><p>But this thing is not very graph-like.</p><p>xyIvneu_  13:36:38</p><p>c  13:36:46</p><p>jnk<br> Graph isomorphism ()</p><p>@jnk Ah, that is exactly what I meant.</p><p>xyIvneu_  13:36:51</p><p>That is why integrated structures like this are hard to explain.</p><p>caution</p><p>caution</p><p>13:41:16</p><p>xyIvneu_<br> It is essentially an iterative method.</p><p>@xyIvneu_ I feel I have an idea, but something also seems wrong.</p><p>caution</p><p>caution</p><p>13:41:49</p><p>What result does this give now? (</p><p>caution</p><p>caution</p><p>13:41:46</p><p>(<em>^▽^</em>)  13:42:24</p><p>Hard to comment on.</p><p>苍孤狼  13:42:57</p><p>I think</p><p>苍孤狼  13:43:24</p><p>caution</p><p>caution</p><p>13:43:32</p><p>Oh, it seems to be 8/23?</p><p>苍孤狼  13:43:36</p><p>The source notation “12” controls the base interval.</p><p>xyIvneu_  13:43:37</p><p>@</p><p>caution</p><p>caution</p><p>☢caution☢caution☢<br> What result does this give now? (</p><p>Theoretically this is 8/17.</p><p>xyIvneu_  13:43:49</p><p>With a favorable phase.</p><p>xyIvneu_  13:43:56</p><p>But with the wrong phase, I do not know.</p><p>苍孤狼  13:44:00</p><p>The factor 3 controls the uniformity of the added intervals.</p><p>caution</p><p>caution</p><p>13:44:02</p><p>I think I am beginning to understand.</p><p>caution</p><p>caution</p><p>13:44:14</p><p>xyIvneu_  13:44:25</p><p>Oh, 8/23 is correct.</p><p>苍孤狼  13:44:26</p><p>Uniform 3 means the intervals of length 3 in 23223 are distributed uniformly.</p><p>xyIvneu_  13:44:28</p><p>I read it wrong.</p><p>caution</p><p>caution</p><p>13:44:41</p><p>@xyIvneu_ My idea is to change this part and turn it into this.</p><p>苍孤狼  13:44:48</p><p>The base interval is 2, determined by 12.</p><p>caution</p><p>caution</p><p>13:45:03</p><p>(<em>^▽^</em>)  13:45:15</p><p>@</p><p>caution</p><p>caution</p><p>☢caution☢caution☢</p><p>@</p><p>caution</p><p>caution</p><p>I calculated that the upper one needs only 8s of startup to change from 13/ [incomplete fraction in the source] to 2/5.</p><p>(<em>^▽^</em>)  13:45:33</p><p>It can be treated as stable output from the fifth output onward.</p><p>caution</p><p>caution</p><p>13:45:41</p><p>Startup means shortening the recirculation path.</p><p>(<em>^▽^</em>)  13:45:49</p><p>Startup is extremely fast.</p><p>caution</p><p>caution</p><p>13:45:50</p><p>Just optimize this a little.</p><p>caution</p><p>caution</p><p>13:46:04</p><p>Do you understand what I mean?</p><p>caution</p><p>caution</p><p>13:46:29</p><p>I wrote that out of habit.</p><p>caution</p><p>caution</p><p>13:46:39</p><p>Not exponentiation—multiplication.</p><p>xyIvneu_  13:47:12</p><p>The best outcome here is optimizing away the Stash in the leap-year method.</p><p>xyIvneu_  13:47:31</p><p>Unfortunately, though, it might not get much smaller.</p><p>xyIvneu_  13:47:45</p><p>But it would still be pretty good.</p><p>xyIvneu_  13:47:47</p><p>Worth a try.</p><p>c  13:48:11</p><p>Does taking the complement of blocking not turn it into splitting? Do you mean splitting can eliminate the Stash?</p><p>Cipolla_  13:48:20</p><p>One advantage of this thing is that its startup duration is easy to calculate.</p><p>Cipolla_  13:48:49</p><p>Unlike some things whose startup duration I still do not know how to calculate.</p></details><p>A quick calculation method from @Orirock, subject to certain restrictions. The latter half of the article includes a method for deciding whether a blocking calculation is correct.</p><p><a href="https://docs.qq.com/doc/DZW5GRmJDQXZDVUtm?groupUin=3q4wmga7eLlb8VFivSCxZw%3D%3D" target="_blank" rel="noreferrer">Splitting</a></p><p>For @Orirock&#39;s new material, see the group file 阻塞的判断及计算.docx (Determining and Calculating Blocking).</p><p><a href="https://www.skland.com/article?id=6033639&amp;c_c=COPY" target="_blank" rel="noreferrer">JNK&#39;s Introductory Article on Blocking Flow</a></p><p>The above article includes a method of constructing splitting through blocking to implement arbitrary rational-rate limiters, and a flow-calculation algorithm that has been shown not always to be correct.</p><details><summary>madSUN&#39;s rules (port flow variables, close to the implementation)</summary><p><strong>1.</strong> Flow conservation</p><p><strong>2.</strong> Assign each edge four variables v_H_in, v_L_in, v_H_out, v_L_out (H = High, L = Low, describing the high/low flow relationships under blocking and flowing conditions) and one binary variable is_blocked indicating whether it is blocked.</p><p style="margin-left:1.5rem;"><strong>2.1.</strong> If is_blocked == 1 (blocked), v = v_H_in = v_L_out; if is_blocked == 0 (not blocked), v = v_L_in = v_H_out. Also require v_H_* &gt; v_L_*. (This rule means blocking and non-blocking are exclusive: it is either blocked or not, and the high flow is always greater than the low flow.)</p><p style="margin-left:1.5rem;"><strong>2.2.</strong> If the upstream component is a Splitter, its downstream edges share v_H_in; if the downstream component is a Converger, its upstream edges share v_H_out. (This corresponds to equal flows among a Splitter&#39;s non-blocked downstream edges and a Converger&#39;s blocked upstream edges.)</p><p><strong>3.</strong> Outputs are not blocked.</p></details><details><summary>恒星泰斗&#39;s rules (whether ports are serviced round-robin)</summary><p>Round-robin ports have the maximum flow rate.</p><p>Round-robin ports have equal flow rates.</p><p>Total inflow and outflow at each node are equal.</p><p>Full rank (the flow relationships admit no multiple solutions).</p></details><details><summary>Cipolla_&#39;s rules (blocking/flowing and full belts)</summary><ol><li><p>A Splitter&#39;s upstream is flowing &lt;=&gt; at least one downstream edge is flowing.</p></li><li><p>A Splitter&#39;s upstream is blocked &lt;=&gt; all downstream edges are blocked (invalid when the upstream belt is full).</p></li><li><p>A Converger&#39;s downstream is blocked ＜=＞ at least one of its upstream edges is blocked.</p></li><li><p>A Converger&#39;s downstream is flowing &lt;=&gt; all upstream edges are flowing (invalid when the downstream belt is full).</p></li><li><p>When a Splitter has a flowing downstream branch, all branches with the highest flow rate are flowing; all other branches are not flowing.</p></li><li><p>When a Converger has a blocked upstream branch, all branches with the highest flow rate are blocked; all other branches are not blocked.</p></li><li><p>Every belt must be flowing or blocked, and may be both. A full belt must be both flowing and blocked.</p></li><li><p>Flow conservation.</p></li><li><p>All system inputs are blocked, and all outputs are flowing.</p></li></ol></details><details><summary>jnk&#39;s rules (three states of blocking/flowing and full belts)</summary><p>0．Every belt must occupy one of three states: non-blocked, both flowing and blocked, or non-flowing.<br> 1．If a Splitter&#39;s input is flowing, at least one output is flowing; if every output is non-flowing, its input is non-flowing.<br> 2．If a Splitter&#39;s input is non-flowing, at least one output is non-flowing.<br> 3．If a Splitter&#39;s input is non-blocked, at least one output is non-blocked.<br> 4．All flowing outputs of a Splitter have equal flow rates; non-flowing outputs do not exceed that rate.<br> 5．If a Splitter&#39;s input is non-flowing and a flowing output exists, that input&#39;s flow rate is 1.<br> 6．If a Converger&#39;s output is non-flowing, at least one input is non-flowing.<br> 7．If a Converger&#39;s output is non-blocked, all inputs are non-blocked.<br> 8．All blocked inputs of a Converger have equal flow rates; non-blocked inputs do not exceed that rate.<br> 9．If a Converger&#39;s input is non-flowing and its output is flowing, that input&#39;s flow rate is 1.<br> 10．Flow conservation; all system outputs are non-blocked. Source output edges have equal flow rates and, when non-blocked, must carry real flow.<br> (Linear-programming solution rule) Every flowing edge has flow at least the global minimum; the objective is to maximize that minimum.</p></details><details><summary>The logistics-system naming debate—chat transcript</summary><p>君 2026/8/6 20:50:05<br> Why call it classical? (</p><p>jnk 2026/8/6 20:50:11<br> No idea.</p><p>madSUN 2026/8/6 20:50:15<br> No idea.</p><p>c 2026/8/6 20:50:17<br> No idea.</p><p>kokobird 2026/8/6 20:50:23<br> Damn (</p><p>kokobird 2026/8/6 20:50:41<br> But why does the name actually feel so appropriate?</p><p>Cipolla_ 2026/8/6 20:50:43<br> It needs some name, after all.</p><p>君 2026/8/6 20:50:47<br> Give us a modern system (?)</p><p>c 2026/8/6 20:51:15<br> 4n, 1 stall (</p><p>jnk 2026/8/6 20:51:25<br> Actually, is Cipolla_ not the only person in the group insisting on ‘classical system’? (</p><p>kokobird 2026/8/6 20:51:25<br> Does it suggest independence from placement order?</p><p>jnk 2026/8/6 20:53:05<br> I say call it an equivalent-graph logistics system, or graph logistics system for short. (</p><p>madSUN 2026/8/6 20:53:24<br> jnk<br> I say call it an equivalent-graph logistics system, or graph logistics system for short. (<br> That works.</p><p>madSUN 2026/8/6 20:53:39<br> Or idealized logistics system.</p><p>jnk 2026/8/6 20:54:10<br> madSUN<br> Or idealized logistics system.<br> Idealized is good. It really is quite idealized.</p><p>Cipolla_ 2026/8/6 21:01:22<br> 君<br> Why call it classical? (<br> @君 I took inspiration from the classical probability model. The name felt appropriate, so I used it.</p><p>Cipolla_ 2026/8/6 21:02:46<br> I originally wanted to call it a simple system, but it apparently is not simple at all.</p><p>Cipolla_ 2026/8/6 21:10:41<br> There is actually a lot to naming this system.</p><p>Cipolla_ 2026/8/6 21:11:27<br> A term like ‘classical system’ is unforgettable after seeing it a few times, which is good in a sense.</p><p>Cipolla_ 2026/8/6 21:12:37<br> Of course, perhaps it is just me who does not forget easily. I do not know how you feel.</p><p>桜夜天華 2026/8/6 21:13:27<br> Pretty good.</p><p>桜夜天華 2026/8/6 21:13:31<br> Classical probability model.</p><p>桜夜天華 2026/8/6 21:13:34<br> classic</p><p>桜夜天華 2026/8/6 21:13:44<br> Independent of version.</p><p>madSUN 2026/8/6 21:21:03<br> 桜夜天華<br> classic<br> Somehow I actually think ‘classic’ is better than 古典 (classical). Why?</p><p>jnk 2026/8/6 21:22:55<br> Cipolla_<br> Of course, perhaps it is just me who does not forget easily. I do not know how you feel.<br> Whether memorable or not, it is not great if nobody can understand the name at first glance after studying any of our current theories. ‘Equivalent-graph logistics system’: anyone who has learned blocking flow knows it means the system they studied, requiring buffering and having no priorities. ‘Idealized logistics system’: anyone familiar with the bugs knows the ideal case excludes them—a system disregarding bugs. But ‘classical system’? We cannot have people who studied classical probability asking for a Bayesian-school system, preferring new knowledge to old, lol.</p><p>桜夜天華 2026/8/6 21:24:13<br> Call it a general system.</p><p>桜夜天華 2026/8/6 21:24:25<br> Simple system.</p><p>桜夜天華 2026/8/6 21:24:29<br> Classic system.</p><p>桜夜天華 2026/8/6 21:24:35<br> Or whatever.</p><p>c 2026/8/6 21:24:47<br> Even so, should it not be proved first? (</p><p>c 2026/8/6 21:24:51<br> The name is secondary.</p><p>Cipolla_ 2026/8/6 21:26:58<br> jnk<br> Whether memorable or not, it is not great if nobody can understand the name at first glance after studying any of our current theories. ‘Equivalent-graph logistics system’: anyone who has learned blocking flow knows it means the system they studied, requiring buffering and having no priorities. ‘Idealized logistics system’: anyone familiar with the bugs knows the ideal case excludes them—a system disregarding bugs. But ‘classical system’? We cannot have people who studied classical probability asking for a Bayesian-school system, preferring new knowledge to old, lol.<br> @jnk I actually think it is hard for a name to convey much directly.</p><p>Cipolla_ 2026/8/6 21:27:19<br> Forget it; the name is a minor issue.</p><p>jnk 2026/8/6 21:27:40<br> Call it the rolling-log system. (</p><p>c 2026/8/6 21:27:51<br> jnk<br> Call it the rolling-log system. (<br> @jnk Memorable.</p></details><p><a href="/endfield-skydoc/proof-of-flow-rate-uniqueness-for-flow-limiters">Proof of Flow-Rate Uniqueness for Flow Limiters (Cipolla_)</a></p><p><a href="/endfield-skydoc/complete-blocking-flow-theory">Complete Blocking-Flow Theory</a></p><p><a href="https://github.com/hongshan-academy/TopoConstructor" target="_blank" rel="noreferrer">Code for Constructing Particular Flow-Limiting Structures</a> from @madSUN</p><blockquote><p>Translation note: The transcript writes “12” in its base-interval discussion; the available text does not establish whether this means twelve or ports 1 and 2. The fraction written “13/” is also retained as source notation and appears incomplete; it has not been guessed as 1/3.</p></blockquote></div>',1)])])}const d=t(n,[["render",a]]);export{m as __pageData,d as default};
